#!/bin/bash
# KADIMA Gamma red-reduction, 2026-10-22 (trader decisions from the 21-Oct Gamma Blast audit).
#   R2 open_blackout: no gamma entry before 09:45 IST            (trend_rules.json switch, live)
#   R3 exhaustion:    no same-side gamma on an index for 30 min after an earlier gamma hit +50%
#   Threshold 50:     celestial + trade_policy accept 50/55 (and trade_policy now accepts 60,
#                     which it silently rejected since 20-Oct); Celestial threshold set to 50
#   volume_unconfirmed becomes a note, not a blocker
# R1 (counter-trend gamma) is already live via trend_rules.json mode=live; unchanged.
# Run on EC2 OUTSIDE market hours.
#   bash deploy/deploy_gamma_red_reduction_20261022.sh              # gates, backup, install 3 files, switches live, threshold 50, restart, health
#   bash deploy/deploy_gamma_red_reduction_20261022.sh --shadow     # R2+R3 to shadow (log only), no restart
#   bash deploy/deploy_gamma_red_reduction_20261022.sh --rollback   # threshold 60, switches removed, restore the 3 files, restart
set -u
ROOT=${KADIMA_ROOT:-$HOME/kadima-py}
K=$ROOT/kadima
FILES="trend_rules celestial trade_policy"
declare -A BASE=( [trend_rules]="a33bb6dca54086144dee08209e6c7f8ac2ea539c48e42498ec0505060eb6fb94 8481cb3ab89bbabb4d75942cc4641a517fd6f7f404375b5e9c82ad8e459c3456" [celestial]=f70ae5fc03854f0462e51870f4584d66ee4a77c200de0d6374e236593c16ad6f [trade_policy]=bf3c320116318ca714c26e4b096039c658e2a6b0b8a735abb8b6d3f7b70b2208 )
declare -A NEW=( [trend_rules]=bad4019dba0a15ee6a508afd35190236f8dc6e3f0a45f679ec8f9ebeddf7d731 [celestial]=8cf59c7b34f470b540b11dcbc2b1ff2c3ce8fe4fce3898a989a5f98fe8d38df9 [trade_policy]=6d204fc261fa29c81830db45077891b4323d76ccb5282c873a2657231ebb6c4a )
declare -A PAY=( [trend_rules]='' [celestial]='' [trade_policy]='' )
TAG=bak-gamma-red-20261022
DATA=$(systemctl show kadima -p Environment --value | tr ' ' '\n' | sed -n 's/^KADIMA_DATA_DIR=//p'); DATA=${DATA:-/var/lib/kadima}
CFG=$DATA/trend_rules.json
OWNER=$(stat -c %U "$DATA/kadima.db")
h() { sha256sum "$1" 2>/dev/null | cut -c1-64; }
switches() {
  sudo python3 - "$CFG" "$1" <<'PY'
import json, os, sys
path, value = sys.argv[1], sys.argv[2]
try:
    cfg = json.load(open(path)) if os.path.exists(path) else {}
except ValueError:
    cfg = {}
for key in ('open_blackout', 'exhaustion'):
    if value == 'remove':
        cfg.pop(key, None)
    else:
        cfg[key] = value
cfg.setdefault('mode', 'shadow')
st = os.stat(path) if os.path.exists(path) else None
open(path, 'w').write(json.dumps(cfg, indent=1))
if st: os.chown(path, st.st_uid, st.st_gid)
print('trend_rules.json', json.dumps(cfg))
PY
}
threshold() {
  ( cd "$ROOT" && sudo -u "$OWNER" env KADIMA_DATA_DIR="$DATA" "$ROOT/venv/bin/python" -c "
from kadima import celestial
cfg = celestial.update_config({'score_threshold': $1})
print('celestial threshold', cfg['score_threshold'], 'auto_trade_enabled', cfg['auto_trade_enabled'], 'revision', cfg['revision'])
" ) || { echo "WARN: could not set Celestial threshold to $1; set it from the dashboard"; return 1; }
}
health() {
  sleep 25
  systemctl is-active --quiet kadima || { echo "HEALTH FAIL: kadima not active"; return 1; }
  if journalctl -u kadima --since "-1 min" --no-pager | grep -q "Traceback"; then echo "HEALTH FAIL: traceback"; return 1; fi
  echo "health ok"; return 0
}
restore() {
  for f in $FILES; do [ -f "$K/$f.py.$TAG" ] && cp -p "$K/$f.py.$TAG" "$K/$f.py"; done
}
if [ "${1:-}" = "--shadow" ]; then switches shadow; echo "R2+R3 shadow (re-read within 30 s)"; exit; fi
if [ "${1:-}" = "--rollback" ]; then
  threshold 60; switches remove; restore; sudo systemctl restart kadima && health
  for f in $FILES; do echo "$f $(h $K/$f.py | cut -c1-12)"; done; exit
fi
echo "== 1. gates"
HM=$(TZ=Asia/Kolkata date +%H%M); DOW=$(TZ=Asia/Kolkata date +%u)
if [ "$DOW" -le 5 ] && [ "$HM" -ge 0900 ] && [ "$HM" -lt 1545 ]; then echo "ABORT: market hours (IST $HM); run after 15:45 or before 09:00"; exit 1; fi
for f in $FILES; do
  CUR=$(h $K/$f.py)
  if [ "$CUR" = "${NEW[$f]}" ]; then echo "$f already installed"; continue; fi
  case " ${BASE[$f]} " in *" $CUR "*) echo "$f base ok ${CUR:0:12}";; *) echo "ABORT: live $f.py ${CUR:0:12} is not a known base; nothing changed"; exit 1;; esac
done
echo "== 2. stage + verify"
for f in $FILES; do
  [ "$(h $K/$f.py)" = "${NEW[$f]}" ] && continue
  echo "${PAY[$f]}" | base64 -d | gunzip > "$K/$f.py.new-gamma-red"
  [ "$(h $K/$f.py.new-gamma-red)" = "${NEW[$f]}" ] || { rm -f $K/*.new-gamma-red; echo "ABORT: $f payload hash mismatch"; exit 1; }
  "$ROOT/venv/bin/python" -m py_compile "$K/$f.py.new-gamma-red" || { rm -f $K/*.new-gamma-red; echo "ABORT: $f does not compile"; exit 1; }
done
echo "== 3. backup + install"
for f in $FILES; do
  [ -f "$K/$f.py.new-gamma-red" ] || continue
  cp -p "$K/$f.py" "$K/$f.py.$TAG"; mv "$K/$f.py.new-gamma-red" "$K/$f.py"; echo "$f installed, backup $f.py.$TAG"
done
echo "== 4. switches + threshold"
switches live
threshold 50
echo "== 5. restart"; sudo systemctl restart kadima
if ! health; then
  echo "ROLLING BACK"; threshold 60; switches remove; restore; sudo systemctl restart kadima; health; exit 1
fi
echo "DONE: R2 09:45 blackout + R3 30-min exhaustion live, threshold 50, volume note-only"
